import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap'; // optional import for future timelines

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Determine aspect ratio from supplied image dimensions (512x320) if needed
  const aspect = 512 / 320; // fallback constant based on spec
  const geometry = new PlaneGeometry(aspect, 1);

  // Basic material – color fallback to paper palette
  const planeColor = (config?.intent?.visualSpec?.colors?.paper) ?? '#e8ecf2';
  const material = new MeshBasicNodeMaterial({ color: planeColor });

  // Create plane mesh
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture if an image URL is provided
  if (config?.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Render any text content using the font atlas
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const text = typeof item === 'string' ? item : item.text ?? item.content ?? '';
    const fontSize = item.typography?.fontSize ?? 39;
    const color = (config?.intent?.visualSpec?.colors?.ink) ?? '#16161d';

    const textObj = ctx.fontAtlas.createText(text, {
      fontSize,
      color,
      align: 'center',
    });

    // Slight offset in front of the plane to avoid z‑fighting
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
  }

  // Apply cinematic primitives if any are listed (none in this spec but kept for completeness)
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const handler = ctx.primitives[prim.name](root, prim.params);
    primitiveHandles.push(handler);
  }

  // User data for cleanup and event handlers
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose texture if it was loaded
    if (material.map) {
      material.map.dispose();
    }

    // Cleanup any primitive resources
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }

    // Kill any GSAP timelines that might have been created (none in this static node)
    gsap.killTweensOf(root);
  };

  return root;
}
